// internal/monitor - the whole trusted core; the exported API is the enumeration
package monitor

type decision struct{ allow bool }               // unexported: callers cannot forge a decision

func Check(ctx context.Context, act Action, id ObjectID) (bool, error) {
    subject, ok := Principal(ctx)                // missing identity is an error, not a pass
    if !ok {
        return false, ErrNoPrincipal
    }
    return policy.Allows(subject, act, id), nil  // policy is unexported and read-only
}
